fn query_expr_children<'a>(
    b: &mut FlatBufferBuilder<'a>,
    object: &Map<String, Value>,
    name: &str,
    path: &str,
) -> Result<
    Option<WIPOffset<flatbuffers::Vector<'a, flatbuffers::ForwardsUOffset<api::QueryExpr<'a>>>>>,
    JsonCodecError,
> {
    let Some(value) = field(object, name) else {
        return Ok(None);
    };
    let values = array(value, &format!("{path}.{name}"))?
        .iter()
        .enumerate()
        .map(|(index, value)| query_expr(b, value, &format!("{path}.{name}[{index}]")))
        .collect::<Result<Vec<_>, _>>()?;
    Ok(Some(b.create_vector(&values)))
}

fn weighted_query_items<'a>(
    b: &mut FlatBufferBuilder<'a>,
    value: &Value,
    path: &str,
) -> Result<
    WIPOffset<flatbuffers::Vector<'a, flatbuffers::ForwardsUOffset<api::WeightedQueryItem<'a>>>>,
    JsonCodecError,
> {
    let values = array(value, path)?
        .iter()
        .enumerate()
        .map(|(index, value)| {
            let object = object(value, &format!("{path}[{index}]"))?;
            check_keys(
                object,
                "SearchKernel_V2_WeightedQueryItem",
                &format!("{path}[{index}]"),
            )?;
            let key = value_from_json(b, required(object, "key", &format!("{path}[{index}]"))?)?;
            let weight = decimal::<i64>(
                required(object, "weight", &format!("{path}[{index}]"))?,
                &format!("{path}[{index}].weight"),
                "signed 64-bit integer",
            )?;
            Ok(api::WeightedQueryItem::create(
                b,
                &api::WeightedQueryItemArgs {
                    key: Some(key),
                    weight,
                },
            ))
        })
        .collect::<Result<Vec<_>, JsonCodecError>>()?;
    Ok(b.create_vector(&values))
}

fn value_object_from_json<'a>(
    b: &mut FlatBufferBuilder<'a>,
    value: &Value,
    path: &str,
) -> Result<WIPOffset<api::ValueObject<'a>>, JsonCodecError> {
    let entries = map_entries(b, Some(value), path)?;
    let entries = b.create_vector(&entries);
    Ok(api::ValueObject::create(
        b,
        &api::ValueObjectArgs {
            fields: Some(entries),
        },
    ))
}

fn term_query<'a>(
    b: &mut FlatBufferBuilder<'a>,
    o: &Map<String, Value>,
    path: &str,
) -> Result<WIPOffset<api::TermQuery<'a>>, JsonCodecError> {
    check_keys(o, "SearchKernel_V2_TermQuery", path)?;
    let value = field(o, "value")
        .map(|raw| value_from_json(b, raw))
        .transpose()?;
    Ok(api::TermQuery::create(b, &api::TermQueryArgs { value }))
}

fn analyze<'a>(
    b: &mut FlatBufferBuilder<'a>,
    o: &Map<String, Value>,
) -> Result<WIPOffset<UnionWIPOffset>, JsonCodecError> {
    check_keys(o, "SearchKernel_V2_AnalyzeRequest", "analyze")?;
    let (target_type, target) = match field(o, "target") {
        None => (api::AnalyzeTarget::NONE, None),
        Some(value) => {
            let (kind, payload) = one_key(value, "analyze.target")?;
            match kind {
                "none" => {
                    check_empty_object(payload, "analyze.target.none")?;
                    (api::AnalyzeTarget::NONE, None)
                }
                "analyzer" => {
                    let analyzer = analyzer(b, object(payload, "analyze.target.analyzer")?)?;
                    (api::AnalyzeTarget::Analyzer, Some(offset(analyzer)))
                }
                "field" => {
                    let target = analyze_field_target(b, object(payload, "analyze.target.field")?)?;
                    (api::AnalyzeTarget::AnalyzeFieldTarget, Some(offset(target)))
                }
                _ => return Err(contract(format!("unknown analyze target `{kind}`"))),
            }
        }
    };
    let text = optional_string(o, "text", "analyze")?.map(|v| b.create_string(&v));
    let language = optional_string(o, "language", "analyze")?.map(|v| b.create_string(&v));
    Ok(offset(api::AnalyzeRequest::create(
        b,
        &api::AnalyzeRequestArgs {
            target_type,
            target,
            text,
            language,
        },
    )))
}

fn analyzer<'a>(
    b: &mut FlatBufferBuilder<'a>,
    o: &Map<String, Value>,
) -> Result<WIPOffset<api::Analyzer<'a>>, JsonCodecError> {
    check_keys(o, "SearchKernel_V2_Analyzer", "analyzer")?;
    let name = optional_string(o, "name", "analyzer")?.map(|v| b.create_string(&v));
    let version = field(o, "version")
        .map(|v| u32_value(v, "analyzer.version"))
        .transpose()?
        .unwrap_or(0);
    let entries = map_entries(b, o.get("options"), "analyzer.options")?;
    let options = match o.get("options") {
        None => None,
        Some(value) if is_absent_vector(value, "analyzer.options")? => None,
        Some(_) => Some(b.create_vector(&entries)),
    };
    Ok(api::Analyzer::create(
        b,
        &api::AnalyzerArgs {
            name,
            version,
            options,
        },
    ))
}

fn analyze_field_target<'a>(
    b: &mut FlatBufferBuilder<'a>,
    o: &Map<String, Value>,
) -> Result<WIPOffset<api::AnalyzeFieldTarget<'a>>, JsonCodecError> {
    check_keys(
        o,
        "SearchKernel_V2_AnalyzeFieldTarget",
        "analyze.target.field",
    )?;
    let field =
        optional_string(o, "field", "analyze.target.field")?.map(|value| b.create_string(&value));
    Ok(api::AnalyzeFieldTarget::create(
        b,
        &api::AnalyzeFieldTargetArgs { field },
    ))
}

fn enum_name(value: &Value, path: &str) -> Result<String, JsonCodecError> {
    string(value, path)
}

fn describe<'a>(
    b: &mut FlatBufferBuilder<'a>,
    o: &Map<String, Value>,
) -> Result<WIPOffset<UnionWIPOffset>, JsonCodecError> {
    check_keys(o, "SearchKernel_V2_DescribeRequest", "describe")?;
    Ok(offset(api::DescribeRequest::create(
        b,
        &api::DescribeRequestArgs {},
    )))
}

fn inspect_query<'a>(
    b: &mut FlatBufferBuilder<'a>,
    o: &Map<String, Value>,
) -> Result<WIPOffset<UnionWIPOffset>, JsonCodecError> {
    check_keys(o, "SearchKernel_V2_InspectQueryRequest", "inspect_query")?;
    let request = field(o, "request")
        .map(|value| object(value, "inspect_query.request").and_then(|value| search(b, value)))
        .transpose()?;
    Ok(offset(api::InspectQueryRequest::create(
        b,
        &api::InspectQueryRequestArgs { request },
    )))
}

